create or replace function public.sc_touch_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at = now(); return new; end; $$;

drop trigger if exists sc_albums_touch_updated_at on public.sc_albums;
create trigger sc_albums_touch_updated_at before update on public.sc_albums for each row execute function public.sc_touch_updated_at();
drop trigger if exists sc_lyrics_touch_updated_at on public.sc_lyrics;
create trigger sc_lyrics_touch_updated_at before update on public.sc_lyrics for each row execute function public.sc_touch_updated_at();
drop trigger if exists sc_songs_touch_updated_at on public.sc_songs;
create trigger sc_songs_touch_updated_at before update on public.sc_songs for each row execute function public.sc_touch_updated_at();
drop trigger if exists sc_audio_versions_touch_updated_at on public.sc_audio_versions;
create trigger sc_audio_versions_touch_updated_at before update on public.sc_audio_versions for each row execute function public.sc_touch_updated_at();

alter table public.sc_audio_versions add constraint sc_versions_final_implies_primary check (not is_final or is_primary);
create unique index sc_versions_one_primary_per_song on public.sc_audio_versions(song_id) where is_primary;
create unique index sc_versions_one_final_per_song on public.sc_audio_versions(song_id) where is_final;
